import CustomizedButton from "components/common/CustomizedButton";
import React, { useEffect, useState } from "react";

import { Card, Form, Container, Row, Col } from "react-bootstrap";
import { useHistory } from "react-router";
import auth from "utility/auth";
import { axios } from "utility/httpreq";
import notify from "utility/notify";

const AddAgeGroup = () => {
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const history = useHistory();
  const [isLogging, setIsLogging] = useState(false);
  const [roles, setRoles] = useState(null);
  const [formData, setFormData] = useState({
    title: "",
    from: "",
    to: "",
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setIsLogging(true);
      await axios(true).post("/api/age-group/add", formData);
      setIsLogging(false);
      history.push("/admin/agegroup");
      notify.showSuccess("User added successfully");
    } catch (error) {
      setIsLogging(false);
      notify.showError(error.response);
    }
  };
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  let content = (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Add Age Group</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label>Title</label>
                        <Form.Control
                          placeholder="Title"
                          type="text"
                          name="title"
                          value={formData.title}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row>
                    <Col className="pr-1" md="6">
                      <Form.Group>
                        <label htmlFor="exampleInputEmail1">From</label>
                        <Form.Control
                          placeholder="0"
                          type="number"
                          name="from"
                          value={formData.from}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                    <Col className="pl-1" md="6">
                      <Form.Group>
                        <label htmlFor="exampleInputPassword">To</label>
                        <Form.Control
                          placeholder="0"
                          type="number"
                          name="to"
                          value={formData.to}
                          onChange={handleChange}
                          required
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>

                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                        className="btn-fill pull-right"
                        type="submit"
                        variant="info"
                      >
                        Submit
                      </Button> */}
                      <CustomizedButton
                        isDisabled={isLogging}
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );

  if (auth(user)?.isRole("Admin") || auth(user)?.isUserAllowed("view_user")) {
    return content;
  } else {
    return <Redirect to="/admin/dashboard" />;
  }
};

export default AddAgeGroup;
