import React, { useEffect } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPhone, faTimes } from "@fortawesome/fontawesome-free-solid";
import { connect } from "react-redux";
import { connectAction } from "redux/action/messageAction";
const VoiceCall = (props) => {
  const user = JSON.parse(localStorage.getItem("loggedInUser") || {});
  const username = user?.email?.split("@")[0] || "testuser";
  const userEmail = username + `process.env.REACT_APP_CHAT_DOMAIN`;

  let contents = (
    <>
      <div className="voice-call-page">
        <div className="call-header">
          <p className="font-weight-bold"> Ongoing Call </p>
        </div>

        <div className="d-flex align-items-center py-1 flex-column call-body">
          <div className="position-relative">
            <div className="avatar-box bg-light-danger">
              <span className="avatar-label">BM</span>
            </div>
          </div>
          <div className="flex-grow-1">
            <span className="chat-username-sm">Bertha Martin</span>
            <div className="text-muted small text-center">
              <strong> 01: 30 </strong>
            </div>
          </div>
        </div>

        <div className="call-control-btns d-flex justify-content-center w-100">
          <button
            type="button"
            className="mr-4 btn-circle btn-start-call d-md-inline-block btn"
          >
            {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
            <FontAwesomeIcon icon={faPhone} />
          </button>
          <button
            type="button"
            className="mr-4 btn-circle btn-end-call d-md-inline-block btn"
          >
            {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
            <FontAwesomeIcon icon={faTimes} />
          </button>
        </div>
      </div>
    </>
  );

  return contents;
};

const mapDispatchToProps = (dispatch) => ({
  connectXmpp: (jid) => dispatch(connectAction(jid)),
  // setRoster: (roster) => dispatch(setRoster(roster)),
  // retrieveHistory: (user, connection) =>
  //   dispatch(retrieveHistory(user, connection)),
  // sendMessage: (msg) => dispatch(sendMessage(msg)),
  // receiveMessage: (msg) => dispatch(receiveMessage(msg)),
});

const mapStateToProps = (state) => ({
  connection: state.xmpp.connection,
  connected: state.xmpp.connected,
  loading: state.xmpp.loading,
  rosters: state.xmpp.rosters,
  chatHistory: state.xmpp.chatHistory,
});
export default connect(mapStateToProps, mapDispatchToProps)(VoiceCall);
