import { twoDigit } from "helpers/string.helper";
import CONSTANTS from "redux/constants";
import io from "socket.io-client";
import store from "../store";
import { axios } from "utility/httpreq";
let status = {
  connecting: "connecting...",
  connected: "connected",
  disconnected: "disconnected",
  disconnecting: "disconnecting...",
  failed: "failed",
};
const removeMediaTracks = (localStream) => {
  if (localStream) {
    localStream.getTracks().forEach((track) => {
      track.stop();
      localStream.removeTrack(track);
    });
  }
};
let peer = null;
let localStream = null;
let remoteStream = null;
let remoteRTCMessage = null;
let iceCandidatesFromCaller = [];
let pcConfig = {
  iceServers: [
    { urls: ["stun:stun.l.google.com:19302", "stun:stun2.1.google.com:19302"] },
  ],
};
export const socketConnect = () => (dispatch) => {
  const socket = io.connect(process.env.REACT_APP_BASE_URL, {
    extraHeaders: {
      "x-access-token": localStorage.getItem("token"),
    },
  });
  dispatch({
    type: CONSTANTS.SOCKET_STATUS,
    payload: {
      connected: false,
      connecting: true,
    },
  });
  socket.on("connect", () => {
    dispatch({
      type: CONSTANTS.SOCKET_CONNECT,
      payload: {
        socket,
        connected: true,
        connecting: false,
      },
    });
  });

  socket.on("disconnect", () => {
    dispatch({
      type: CONSTANTS.SOCKET_DISCONNECT,
      payload: {
        socket: null,
        connected: false,
        connecting: false,
      },
    });
  });

  socket.on("receive-msg", (data) => {
    console.log("message received ", data);

    if (window?.location?.pathname === "/admin/chat") {
      // check roster if user is not in roster then add user to roster
      const rosters = store.getState()?.io?.rosters;
      if (rosters) {
        const roster = rosters.find((roster) => roster.id === data.from);

        // if (!roster) {
        dispatch(getRosters(JSON.parse(localStorage.getItem("loggedInUser"))._id));
        // }
      }
    }
    dispatch({
      type: CONSTANTS.RECEIVE_MESSAGE,
      payload: data,
    });
  });

  socket.on("new-roster", (data) => {
    console.log("new roster", data);
    dispatch({
      type: CONSTANTS.ADD_ROSTER,
      payload: data,
    });
  });

  socket.on("newCall", (data) => {
    console.log("call incoming", data);
    const { from, to, rtcMessage, caller } = data;
    console.log("rtc message offer from another user is", rtcMessage.sdp);
    remoteRTCMessage = rtcMessage;
    //when other called you
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: {
        from,
        to,
        rtcMessage,
        showModal: true,
        isInitiator: false,
        callUser: caller,
        start: null,
        reference: null,
        duration: "",
        status: "calling",
      },
    });
  });

  socket.on("ICEcandidate", (data) => {
    // console.log(data);
    console.log("GOT ICE candidate");

    let message = data.rtcMessage;

    console.log(message);
    let candidate = new RTCIceCandidate({
      sdpMLineIndex: message.sdpMLineIndex,
      candidate: message.candidate,
    });

    if (peer) {
      console.log("ICE candidate Added");
      peer.addIceCandidate(candidate);
    } else {
      iceCandidatesFromCaller.push(candidate);
    }
  });

  socket.on("callDeclined", (data) => {
    if (peer) {
      peer.removeStream(localStream);
      peer.close();
      peer = null;
    }
    if (localStream) {
      removeMediaTracks(localStream);
    }
    localStream = null;
    remoteStream = null;
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: {
        currentCall: false,
        status: status.disconnected,
        // from: null,
        // to: null,
        // duration: "",
        // reference: null,
        // start: "",
        peer: null,
        localStream: null,
        remoteStream: null,
        rtcMessage: null,
      },
    });
  });
};

export const setCurChatUser = (user) => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CHAT_USER,
    payload: user,
  });
};

export const getRosters = (id) => async (dispatch) => {
  // const response = await axios(true).get(`/api/user/list`);
  const response = await axios(true).get(`/api/user/roster/${id}`);
  if (Array.isArray(response.data.data)) {
    dispatch({
      type: CONSTANTS.GET_ROSTER,
      payload: { rosters: response.data.data },
    });
  }
};

export const retrieveHistory = (userId) => async (dispatch) => {
  try {
    if (userId) {
      const res = await axios(true).get(`/api/message/${userId}`);
      dispatch({
        type: CONSTANTS.RETRIEVE_HISTORY,
        payload: res.data.data,
      });
    }
  } catch (err) {
    console.log(err);
  }
};

export const sendMessage = (message, socket) => (dispatch) => {
  if (
    (message.body && message.body.trim()) ||
    (message.message && message.from && message.to)
  ) {
    socket.emit("send-msg", message);
    dispatch({
      type: CONSTANTS.SEND_MESSAGE,
      payload: message,
    });
  }
};

function handleOnAddStream(event) {
  document.getElementById("user-video").srcObject = event.stream;
  return event.stream;
}

function addMediaTracks(peer, stream) {
  if (stream) {
    stream.getTracks().forEach((track) => {
      peer.addTrack(track, stream);
    });
  }
}

function handleOnTrack(event) {
  console.log("The new track added is ------ ", event.streams[0]);
  console.log("ontrack", event);
  document.getElementById("user-video").srcObject = event.streams[0];
  return event.streams[0];
}

function handleOnConnectionStateChange(peer, dispatch, event) {
  console.log("status check", event.target.connectionState);
  if (
    event.target.connectionState === "disconnected" ||
    event.target.connectionState === "failed"
  ) {
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: { status: status.disconnected },
    });
  }
  switch (peer.connectionState) {
    case "new":
    case "checking":
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: status.connecting },
      });
      break;
    case "connected":
      dispatch(startTimer(Date.now()));
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: status.connected },
      });
      break;
    case "disconnected":
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: status.disconnected },
      });
      break;
    case "closed":
      if (localStream) {
        removeMediaTracks(localStream);
      }
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: status.disconnected },
      });
      break;
    case "failed":
      if (localStream) {
        removeMediaTracks(localStream);
      }
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: status.disconnected },
      });
      break;
    default:
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { status: "connecting...." },
      });
      break;
  }
}

function handleRemoteStreamRemoved(event) {
  console.log("Remote stream removed. Event: ", event);
}

function handleOnIceCandidate(type = "initCall", socket, options = {}, event) {
  // console.table({ event, callToId, socket });
  console.log("ICE candidate event: ", event);
  if (event && event.candidate) {
    console.log("Local ICE candidate");
    console.log({
      sdpMLineIndex: event.candidate.sdpMLineIndex,
      sdpMid: event.candidate.sdpMid,
      candidate: event.candidate.candidate,
    });

    // console.log("TODO: Sending ICE candidate to remote peer");

    let iceCandidateData = {
      rtcMessage: {
        sdpMLineIndex: event.candidate.sdpMLineIndex,
        sdpMid: event.candidate.sdpMid,
        candidate: event.candidate.candidate,
      },
    };

    if (type === "initCall") {
      iceCandidateData = {
        ...iceCandidateData,
        to: options.to,
        from: options.from,
      };
    } else {
      iceCandidateData = {
        ...iceCandidateData,
        to: options.to,
      };
    }
    socket.emit("ICEcandidate", iceCandidateData);
  } else {
    console.log("End of candidates.");
  }
}

function createOfferForCall(peer, socket, user, callToId) {
  peer
    .createOffer({
      offerToReceiveAudio: true,
    })
    .then((sessionDescription) => {
      console.log("session description is", sessionDescription);
      peer
        .setLocalDescription(sessionDescription)
        .then(() => {
          console.log("local description set");
        })
        .catch((err) => {
          console.log(" failed to add local description", err);
        });

      console.log("new offer created", sessionDescription.sdp);
      socket.emit("call", {
        from: user._id,
        to: callToId,
        rtcMessage: sessionDescription,
      });
    })
    .catch((err) => {
      console.log("error in creating offer", err);
    });
}

function createAnswerForCall(peer, socket, to) {
  peer
    .createAnswer()
    .then((sessionDescription) => {
      // adding ice candidates of the user
      if (iceCandidatesFromCaller.length > 0) {
        //I am having issues with call not being processed in real world (internet, not local)
        //so I will push iceCandidates I received after the call arrived, push it and, once we accept
        //add it as ice candidate
        //if the offer rtc message contains all thes ICE candidates we can ingore this.
        for (let i = 0; i < iceCandidatesFromCaller.length; i++) {
          //
          let candidate = iceCandidatesFromCaller[i];
          console.log("ICE candidate Added From queue", candidate);
          try {
            peer
              .addIceCandidate(candidate)
              .then((done) => {
                console.log("ice candidate added");
              })
              .catch((error) => {
                console.log(error);
              });
          } catch (error) {
            console.log(error);
          }
        }
        iceCandidatesFromCaller = [];
        console.log("ICE candidate queue cleared");
      } else {
        console.log("NO Ice candidate in queue");
      }
      // console.log("created answer is", sessionDescription);
      peer.setLocalDescription(sessionDescription);
      socket.emit("answerCall", {
        to: to,
        rtcMessage: sessionDescription,
      });
    })
    .catch((err) => {
      console.log("err or ", err);
    });
}

export const startTimer = (start) => (dispatch) => {
  const getTimeRemaining = () => {
    const total = Date.now() - start;
    const s = Math.floor(total / 1000);
    const seconds = Math.floor(s % 60);
    const minutes = Math.floor((s / 60) % 60);
    const hours = Math.floor((s / 3600) % 24);
    // setTimer(`${twoDigit(hours)}:${twoDigit(minutes)}:${twoDigit(seconds)}`);
    dispatch({
      type: CONSTANTS.SET_CALL_DURATION,
      payload: `${twoDigit(hours)}:${twoDigit(minutes)}:${twoDigit(seconds)}`,
    });
  };
  const reference = setInterval(() => {
    getTimeRemaining();
  }, 1000);

  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: { start: start, reference },
  });
};

export const stopTimer = (reference) => (dispatch) => {
  if (reference) {
    clearInterval(reference);
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: { reference: null, start: null },
    });
  }
};
// handlers
export const initCall = (socket, callToId, callUser) => (dispatch) => {
  console.log("init call");
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: {
      callUser: callUser,
      showModal: true,
      isInitiator: true,
      status: "calling",
      reference: null,
      start: null,
      duration: "",
      // currentCall: true,
    },
  });
  navigator.mediaDevices
    .getUserMedia({ video: false, audio: true })
    .then((currentStream) => {
      peer = new RTCPeerConnection(pcConfig);
      localStream = currentStream;

      //adding media tracks to peer
      addMediaTracks(peer, currentStream);
      //handling remote stream when another user adds stream
      peer.onaddstream = handleOnAddStream;

      //handling remote stream when another user adds or removes stream
      peer.ontrack = handleOnTrack;

      peer.onconnectionstatechange = handleOnConnectionStateChange.bind(
        this,
        peer,
        dispatch
      );

      peer.onicecandidate = handleOnIceCandidate.bind(
        this,
        "initCall",
        socket,
        { to: callToId, from: user._id }
      );

      peer.onremovestream = handleRemoteStreamRemoved;

      peer.oniceconnectionstatechange = (event) => {
        console.log("ice connection state change", event);
      };
      peer.onsignalingstatechange = (event) => {
        console.log("signaling state change", event);
      };
      peer.onicegatheringstatechange = (event) => {
        console.log("ice gathering state change", event);
      };

      document.getElementById("my-video").srcObject = localStream;

      createOfferForCall(peer, socket, user, callToId);

      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: {
          peer: peer,
          localStream: currentStream,
          from: user._id,
          to: callToId,
        },
      });

      socket.on("callAnswered", (data) => {
        //when other accept our call
        remoteRTCMessage = data.rtcMessage;
        console.log("call answered signal from other is", data.rtcMessage);
        peer
          .setRemoteDescription(new RTCSessionDescription(data.rtcMessage))
          .then(() => {
            console.log("answer handeled");
          })
          .catch((err) => {
            console.log("error in setting remote description", err);
          });
      });

      //adding tracks to current peer
    })
    .catch((err) => {
      console.log("error is", err);
    });
};

export const answerCall = (socket, signal, from) => (dispatch) => {
  navigator.mediaDevices
    .getUserMedia({ video: false, audio: true })
    .then((currentStream) => {
      peer = new RTCPeerConnection(pcConfig);
      // setting remote description to peer connection
      console.log("signal for answer call is", remoteRTCMessage);
      console.log("connection state is", peer.connectionState);

      localStream = currentStream;
      dispatch({
        type: CONSTANTS.SET_CALL,
        payload: { localStream: currentStream },
      });

      //adding media tracks to peer
      addMediaTracks(peer, currentStream);

      peer.onaddstream = handleOnAddStream;
      // peer.onaddstream = handleRemoteStreamAdded;

      peer.ontrack = handleOnTrack;
      peer.onicecandidate = handleOnIceCandidate.bind(
        this,
        "answerCall",
        socket,
        {
          to: from,
        }
      );
      peer.onremovestream = handleRemoteStreamRemoved;

      peer.onconnectionstatechange = handleOnConnectionStateChange.bind(
        this,
        peer,
        dispatch
      );

      peer.oniceconnectionstatechange = (event) => {
        console.log("ice connection state change", event);
      };
      peer.onsignalingstatechange = (event) => {
        console.log("signaling state change", event);
      };
      peer.onicegatheringstatechange = (event) => {
        console.log("ice gathering state change", event);
      };

      peer.setRemoteDescription(new RTCSessionDescription(remoteRTCMessage));

      createAnswerForCall(peer, socket, from);

      document.querySelector("#my-video").srcObject = currentStream;
    })
    .catch((err) => {
      console.log("error is", err);
    });
};

export const declineCall = (socket, peer, stream, from, to) => (dispatch) => {
  socket.emit("declineCall", { from, to });
  removeMediaTracks(stream);
  if (peer) {
    console.log("decline call", peer);
    stream ? peer.removeStream(stream) : null;
    peer.close();

    peer = null;
    localStream = null;
    remoteStream = null;
  }
  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: {
      // showModal: false,
      status: status.disconnected,
      peer: null,
      localStream: null,
      remoteStream: null,
      rtcMessage: null,
    },
  });
};

export const muteMic = (stream) => (dispatch) => {
  if (stream) {
    stream.getAudioTracks()[0].enabled = !stream.getAudioTracks()[0].enabled;
    dispatch({
      type: CONSTANTS.SET_CALL,
      payload: { localStream: stream },
    });
  }
};

export const setCallModal = (val) => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CALL_MODAL,
    payload: val,
  });
};

export const setCall = (val) => (dispatch) => {
  dispatch({
    type: CONSTANTS.SET_CALL,
    payload: val,
  });
};
